import psycopg2
import os
from dotenv import load_dotenv

load_dotenv()
local_url = os.getenv('DATABASE_URL_LOCAL', 'postgresql://postgres:lenovo@localhost:5432/sade_db')
conn = psycopg2.connect(local_url)
conn.autocommit = True
cur = conn.cursor()
cur.execute('SET statement_timeout = 0;')

views_to_create = [('mv_catastro_stock_historico', " WITH cfg AS (\n         SELECT cfg_gestion_metas.analistas_oficiales\n           FROM cfg_gestion_metas\n          WHERE ((cfg_gestion_metas.gerencia = 'catastro'::text) AND (cfg_gestion_metas.trata_reporte = 'INTERVENCIONES'::text))\n        ), fechas_corte AS (\n         SELECT ((date_trunc('month'::text, mes.mes) + '1 mon -1 days'::interval))::date AS fecha_corte\n           FROM generate_series((date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone) - '11 mons'::interval), date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone), '1 mon'::interval) mes(mes)\n        ), destinatario_por_corte AS (\n         SELECT DISTINCT ON (u.id_expediente, fc.fecha_corte) u.id_expediente,\n            u.trata,\n            u.es_trata_propia,\n            fc.fecha_corte,\n            p.destinatario AS destinatario_cierre\n           FROM ((mv_catastro_universo u\n             CROSS JOIN fechas_corte fc)\n             JOIN mvw_ee_pases_secgdu p ON (((p.id_expediente = u.id_expediente) AND ((p.fecha)::date <= fc.fecha_corte))))\n          ORDER BY u.id_expediente, fc.fecha_corte, p.fecha DESC\n        ), subsanacion_abierta_al_cierre AS (\n         SELECT DISTINCT ON (dpc_1.id_expediente, dpc_1.fecha_corte) dpc_1.id_expediente,\n            dpc_1.fecha_corte,\n            true AS tiene_subsanacion_abierta\n           FROM (destinatario_por_corte dpc_1\n             JOIN mvw_ee_actividades_secgdu a ON (((a.id_expediente = dpc_1.id_expediente) AND (a.usuario_alta = dpc_1.destinatario_cierre) AND (a.nombre_tipo_actividad = 'SOLICITUD_SUBSANACION_TAD'::text) AND ((a.fecha_alta)::date <= dpc_1.fecha_corte) AND ((a.fecha_cierre IS NULL) OR ((a.fecha_cierre)::date > dpc_1.fecha_corte)))))\n          ORDER BY dpc_1.id_expediente, dpc_1.fecha_corte, a.fecha_alta DESC\n        )\n SELECT dpc.fecha_corte AS mes_cierre,\n    to_char((dpc.fecha_corte)::timestamp with time zone, 'YYYY-MM'::text) AS mes_label,\n    dpc.trata,\n    dpc.es_trata_propia,\n        CASE\n            WHEN COALESCE(sac.tiene_subsanacion_abierta, false) THEN 'SUBSANACION'::text\n            ELSE 'STOCK_PROPIO'::text\n        END AS categoria,\n    count(*) AS cant_expedientes\n   FROM ((destinatario_por_corte dpc\n     LEFT JOIN subsanacion_abierta_al_cierre sac ON (((sac.id_expediente = dpc.id_expediente) AND (sac.fecha_corte = dpc.fecha_corte))))\n     CROSS JOIN cfg)\n  WHERE (dpc.destinatario_cierre = ANY (cfg.analistas_oficiales))\n  GROUP BY dpc.fecha_corte, dpc.trata, dpc.es_trata_propia,\n        CASE\n            WHEN COALESCE(sac.tiene_subsanacion_abierta, false) THEN 'SUBSANACION'::text\n            ELSE 'STOCK_PROPIO'::text\n        END;"), ('mv_catastro_stock_propio', " WITH cfg AS (\n         SELECT cfg_gestion_metas.analistas_oficiales\n           FROM cfg_gestion_metas\n          WHERE ((cfg_gestion_metas.gerencia = 'catastro'::text) AND (cfg_gestion_metas.trata_reporte = 'INTERVENCIONES'::text))\n        )\n SELECT u.id_expediente,\n    u.expediente,\n    u.trata,\n    u.descripcion_trata,\n    u.descripcion,\n    u.caratula,\n    u.estado_expediente,\n    u.fecha_primer_ingreso_gerencia,\n    up.destinatario_actual AS analista,\n    up.fecha_ultimo_pase AS fecha_recepcion_analista,\n    (CURRENT_DATE - (up.fecha_ultimo_pase)::date) AS dias_en_poder_actual,\n    (CURRENT_DATE - (u.fecha_primer_ingreso_gerencia)::date) AS dias_en_gerencia\n   FROM ((mv_catastro_universo u\n     JOIN mv_ultimo_pase up ON ((up.id_expediente = u.id_expediente)))\n     CROSS JOIN cfg)\n  WHERE ((u.es_trata_propia = true) AND (up.destinatario_actual = ANY (cfg.analistas_oficiales)) AND (NOT (EXISTS ( SELECT 1\n           FROM mvw_ee_actividades_secgdu a\n          WHERE ((a.id_expediente = u.id_expediente) AND (a.estado = 'PENDIENTE'::text) AND (a.nombre_tipo_actividad = 'SOLICITUD_SUBSANACION_TAD'::text))))));"), ('mv_catastro_universo', " WITH cfg AS (\n         SELECT cfg_gestion_metas.tratas_incluidas,\n            cfg_gestion_metas.buzones_ingreso,\n            cfg_gestion_metas.buzones_ingreso_intervenciones\n           FROM cfg_gestion_metas\n          WHERE ((cfg_gestion_metas.gerencia = 'catastro'::text) AND (cfg_gestion_metas.trata_reporte = 'INTERVENCIONES'::text))\n        ), ingresos_propios AS (\n         SELECT pib.id_expediente,\n            min(pib.fecha_primer_ingreso) AS fecha_min,\n            (array_agg(pib.buzon ORDER BY pib.fecha_primer_ingreso))[1] AS primer_buzon\n           FROM (mv_primer_ingreso_buzon pib\n             CROSS JOIN cfg cfg_1)\n          WHERE (pib.buzon = ANY (cfg_1.buzones_ingreso))\n          GROUP BY pib.id_expediente\n        ), ingresos_intervenciones AS (\n         SELECT pib.id_expediente,\n            min(pib.fecha_primer_ingreso) AS fecha_min,\n            (array_agg(pib.buzon ORDER BY pib.fecha_primer_ingreso))[1] AS primer_buzon\n           FROM (mv_primer_ingreso_buzon pib\n             CROSS JOIN cfg cfg_1)\n          WHERE (pib.buzon = ANY (cfg_1.buzones_ingreso_intervenciones))\n          GROUP BY pib.id_expediente\n        )\n SELECT e.id_expediente,\n    e.expediente,\n    e.trata,\n    e.descripcion_trata,\n    e.descripcion,\n    e.caratula,\n    up.estado_en_pase AS estado_expediente,\n    e.fecha_creacion AS fecha_creacion_ee,\n        CASE\n            WHEN (e.trata = ANY (cfg.tratas_incluidas)) THEN ip.primer_buzon\n            ELSE ii.primer_buzon\n        END AS primer_buzon_ingreso,\n        CASE\n            WHEN (e.trata = ANY (cfg.tratas_incluidas)) THEN ip.fecha_min\n            ELSE ii.fecha_min\n        END AS fecha_primer_ingreso_gerencia,\n    (e.trata = ANY (cfg.tratas_incluidas)) AS es_trata_propia\n   FROM ((((mvw_expedientes_tratas_secgdu e\n     CROSS JOIN cfg)\n     LEFT JOIN mv_ultimo_pase up ON ((up.id_expediente = e.id_expediente)))\n     LEFT JOIN ingresos_propios ip ON ((ip.id_expediente = e.id_expediente)))\n     LEFT JOIN ingresos_intervenciones ii ON ((ii.id_expediente = e.id_expediente)))\n  WHERE (((e.trata = ANY (cfg.tratas_incluidas)) AND (ip.id_expediente IS NOT NULL)) OR ((NOT (e.trata = ANY (cfg.tratas_incluidas))) AND (ii.id_expediente IS NOT NULL)));"), ('mv_catastro_subsanaciones', " WITH cfg AS (\n         SELECT cfg_gestion_metas.analistas_oficiales\n           FROM cfg_gestion_metas\n          WHERE ((cfg_gestion_metas.gerencia = 'catastro'::text) AND (cfg_gestion_metas.trata_reporte = 'INTERVENCIONES'::text))\n        ), subs_abiertas AS (\n         SELECT DISTINCT ON (mvw_ee_actividades_secgdu.id_expediente) mvw_ee_actividades_secgdu.id_expediente,\n            mvw_ee_actividades_secgdu.usuario_alta,\n            mvw_ee_actividades_secgdu.nombre_tipo_actividad,\n            mvw_ee_actividades_secgdu.fecha_alta\n           FROM mvw_ee_actividades_secgdu\n          WHERE ((mvw_ee_actividades_secgdu.estado = 'PENDIENTE'::text) AND (mvw_ee_actividades_secgdu.nombre_tipo_actividad = 'SOLICITUD_SUBSANACION_TAD'::text))\n          ORDER BY mvw_ee_actividades_secgdu.id_expediente, mvw_ee_actividades_secgdu.fecha_alta DESC\n        )\n SELECT u.id_expediente,\n    u.expediente,\n    u.trata,\n    u.descripcion_trata,\n    u.descripcion,\n    u.caratula,\n    u.estado_expediente,\n    u.fecha_primer_ingreso_gerencia,\n    up.destinatario_actual AS analista,\n    up.fecha_ultimo_pase AS fecha_recepcion_analista,\n    (CURRENT_DATE - (up.fecha_ultimo_pase)::date) AS dias_en_poder_actual,\n    sa.nombre_tipo_actividad AS tipo_subsanacion,\n    sa.fecha_alta AS fecha_apertura_subsanacion,\n    (CURRENT_DATE - (sa.fecha_alta)::date) AS dias_subsanacion_abierta,\n    (CURRENT_DATE - (u.fecha_primer_ingreso_gerencia)::date) AS dias_en_gerencia\n   FROM (((mv_catastro_universo u\n     JOIN mv_ultimo_pase up ON ((up.id_expediente = u.id_expediente)))\n     CROSS JOIN cfg)\n     JOIN subs_abiertas sa ON ((sa.id_expediente = u.id_expediente)))\n  WHERE ((u.es_trata_propia = true) AND (up.destinatario_actual = ANY (cfg.analistas_oficiales)));"), ('mv_catastro_egresos_efectivos', " WITH reglas_por_trata AS (\n         SELECT cfg.trata_reporte AS trata,\n            unnest(cfg.acronimos_egreso) AS acronimo,\n            cfg.firmantes_egreso\n           FROM cfg_gestion_metas cfg\n          WHERE ((cfg.gerencia = 'catastro'::text) AND (cfg.trata_reporte <> 'INTERVENCIONES'::text))\n        ), egresos_validos AS (\n         SELECT u.id_expediente,\n            u.expediente,\n            u.trata,\n            u.descripcion_trata,\n            u.descripcion,\n            u.caratula,\n            u.fecha_primer_ingreso_gerencia,\n            d.documento AS documento_egreso,\n            d.acronimo AS acronimo_egreso,\n            d.fecha_asociacion AS fecha_egreso,\n            d.usuario_creador AS usuario_egreso,\n            row_number() OVER (PARTITION BY u.id_expediente ORDER BY d.fecha_asociacion) AS rn\n           FROM ((mv_catastro_universo u\n             JOIN reglas_por_trata r ON ((r.trata = u.trata)))\n             JOIN mvw_datos_gedo_secgdu d ON (((d.id_expediente = u.id_expediente) AND (d.acronimo = r.acronimo) AND ((r.firmantes_egreso IS NULL) OR (d.usuario_creador = ANY (r.firmantes_egreso))) AND (d.fecha_asociacion >= u.fecha_primer_ingreso_gerencia))))\n          WHERE ((u.es_trata_propia = true) AND ((u.trata <> 'MDUG0134N'::text) OR (EXISTS ( SELECT 1\n                   FROM mvw_ee_pases_secgdu p\n                  WHERE ((p.id_expediente = u.id_expediente) AND (p.motivo ~* 'constituc|certific'::text))))))\n        )\n SELECT egresos_validos.id_expediente,\n    egresos_validos.expediente,\n    egresos_validos.trata,\n    egresos_validos.descripcion_trata,\n    egresos_validos.descripcion,\n    egresos_validos.caratula,\n    egresos_validos.fecha_primer_ingreso_gerencia,\n    egresos_validos.documento_egreso,\n    egresos_validos.acronimo_egreso,\n    egresos_validos.fecha_egreso,\n    egresos_validos.usuario_egreso,\n    ((egresos_validos.fecha_egreso)::date - (egresos_validos.fecha_primer_ingreso_gerencia)::date) AS dias_tramitacion\n   FROM egresos_validos\n  WHERE (egresos_validos.rn = 1);"), ('mv_catastro_gedos_egreso', " WITH reglas_por_trata AS (\n         SELECT cfg.trata_reporte AS trata,\n            unnest(cfg.acronimos_egreso) AS acronimo,\n            cfg.firmantes_egreso\n           FROM cfg_gestion_metas cfg\n          WHERE ((cfg.gerencia = 'catastro'::text) AND (cfg.trata_reporte <> 'INTERVENCIONES'::text))\n        ), raw_gedos AS (\n         SELECT u.id_expediente,\n            u.expediente,\n            u.trata,\n            u.descripcion_trata,\n            d.documento AS documento_egreso,\n            d.acronimo AS acronimo_egreso,\n            d.fecha_asociacion AS fecha_egreso,\n            d.usuario_creador AS usuario_egreso,\n            row_number() OVER (PARTITION BY u.id_expediente ORDER BY d.fecha_asociacion DESC, d.documento DESC) AS rn\n           FROM ((mv_catastro_universo u\n             JOIN reglas_por_trata r ON ((r.trata = u.trata)))\n             JOIN mvw_datos_gedo_secgdu d ON (((d.id_expediente = u.id_expediente) AND (d.acronimo = r.acronimo) AND ((r.firmantes_egreso IS NULL) OR (d.usuario_creador = ANY (r.firmantes_egreso))) AND (d.fecha_asociacion >= u.fecha_primer_ingreso_gerencia))))\n          WHERE ((u.es_trata_propia = true) AND ((u.trata <> 'MDUG0134N'::text) OR (EXISTS ( SELECT 1\n                   FROM mvw_ee_pases_secgdu p\n                  WHERE ((p.id_expediente = u.id_expediente) AND (p.motivo ~* 'constituc|certific'::text))))))\n        )\n SELECT raw_gedos.id_expediente,\n    raw_gedos.expediente,\n    raw_gedos.trata,\n    raw_gedos.descripcion_trata,\n    raw_gedos.documento_egreso,\n    raw_gedos.acronimo_egreso,\n    raw_gedos.fecha_egreso,\n    raw_gedos.usuario_egreso\n   FROM raw_gedos\n  WHERE (raw_gedos.rn = 1);"), ('mv_catastro_egresos_no_efectivos', " SELECT u.id_expediente,\n    u.expediente,\n    u.trata,\n    u.descripcion_trata,\n    u.descripcion,\n    u.caratula,\n    u.estado_expediente,\n    u.fecha_primer_ingreso_gerencia,\n    up.fecha_ultimo_pase AS fecha_ultimo_movimiento,\n    up.destinatario_actual AS poseedor_actual,\n    (CURRENT_DATE - (up.fecha_ultimo_pase)::date) AS dias_desde_guarda,\n    ((up.fecha_ultimo_pase)::date - (u.fecha_primer_ingreso_gerencia)::date) AS dias_tramitacion_aprox\n   FROM ((mv_catastro_universo u\n     JOIN mv_ultimo_pase up ON ((up.id_expediente = u.id_expediente)))\n     LEFT JOIN mv_catastro_egresos_efectivos eef ON ((eef.id_expediente = u.id_expediente)))\n  WHERE ((u.es_trata_propia = true) AND (u.estado_expediente = 'Guarda Temporal'::text) AND (eef.id_expediente IS NULL));")]

for name, definition in views_to_create:
    print(f'Replicando {name} desde prod a local...')
    cur.execute(f'DROP MATERIALIZED VIEW IF EXISTS {name} CASCADE;')
    clean_def = definition.strip().rstrip(';')
    cur.execute(f'CREATE MATERIALIZED VIEW {name} AS {clean_def} WITH DATA;')
    print(f'  -> {name} creada.')

print('Creando indices...')
cur.execute('CREATE INDEX IF NOT EXISTS idx_catastro_ee_id ON mv_catastro_egresos_efectivos(id_expediente);')
cur.execute('CREATE INDEX IF NOT EXISTS idx_catastro_ee_trata ON mv_catastro_egresos_efectivos(trata);')
cur.execute('CREATE INDEX IF NOT EXISTS idx_catastro_ge_id ON mv_catastro_gedos_egreso(id_expediente);')
cur.execute('CREATE INDEX IF NOT EXISTS idx_catastro_ge_trata ON mv_catastro_gedos_egreso(trata);')
cur.execute('CREATE INDEX IF NOT EXISTS idx_catastro_ene_id ON mv_catastro_egresos_no_efectivos(id_expediente);')
cur.execute('CREATE INDEX IF NOT EXISTS idx_catastro_ene_trata ON mv_catastro_egresos_no_efectivos(trata);')
cur.execute('CREATE INDEX IF NOT EXISTS idx_catastro_sp_id ON mv_catastro_stock_propio(id_expediente);')
cur.execute('CREATE INDEX IF NOT EXISTS idx_catastro_sp_trata ON mv_catastro_stock_propio(trata);')
cur.execute('CREATE INDEX IF NOT EXISTS idx_catastro_subs_id ON mv_catastro_subsanaciones(id_expediente);')
cur.execute('CREATE INDEX IF NOT EXISTS idx_catastro_subs_trata ON mv_catastro_subsanaciones(trata);')
cur.execute('CREATE INDEX IF NOT EXISTS idx_catastro_sh_corte ON mv_catastro_stock_historico(mes_cierre, trata);')
print('Todas las vistas e indices de Catastro replicadas exactamente desde Producción!')
